package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;
public final class EquipmentEditor {
 private static String manage(Activity a,String action,JSONObject req)throws Exception{return (String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,req.toString());}
 public static void attach(Activity a,LinearLayout panel,JSONObject player){for(int section=0;section<3;section++){final int kind=section;Button button=new Button(a);button.setAllCaps(false);button.setText(kind==0?"Sleeves · Undershirt · Socks":kind==1?"Accessories":"Card Background");button.setOnClickListener(v->{button.setEnabled(false);new Thread(()->{try{JSONObject data=new JSONObject(manage(a,"ui710_equipment_get",player));a.runOnUiThread(()->{button.setEnabled(true);if(!a.isFinishing())form(a,player,data,kind);});}catch(Exception e){a.runOnUiThread(()->{button.setEnabled(true);error(a,e);});}},"EquipmentLoad").start();});panel.addView(button,new LinearLayout.LayoutParams(-1,-2));}}
 private static void error(Activity a,Exception e){new AlertDialog.Builder(a).setTitle("Appearance").setMessage(String.valueOf(e.getCause()==null?e:e.getCause())).setPositiveButton("Close",null).show();}
 private static Spinner spinner(Activity a,LinearLayout col,String title,String[] choices,int current){TextView t=new TextView(a);t.setText(title);col.addView(t);Spinner s=new Spinner(a);ArrayAdapter<String> ad=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,choices);ad.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(ad);s.setSelection(current);col.addView(s,new LinearLayout.LayoutParams(-1,-2));return s;}
 private static void form(Activity a,JSONObject player,JSONObject data,int section){try{JSONObject previous=data.optJSONObject("values");if(previous==null)previous=new JSONObject();final JSONObject values=new JSONObject(previous.toString());LinearLayout col=new LinearLayout(a);col.setOrientation(1);int pad=(int)(16*a.getResources().getDisplayMetrics().density);col.setPadding(pad,pad,pad,pad);ScrollView scroll=new ScrollView(a);scroll.addView(col);TextView info=new TextView(a);info.setText("Applies to this card only. Save before Enter Game, then close and reopen the app. Goalkeeper gloves are excluded.");col.addView(info);Spinner sleeve=null,bg=null,socks=null;Spinner[] gear=new Spinner[8];long[] donors=new long[8];
 if(section==0){String old=values.optString("sleeve","none");sleeve=spinner(a,col,"Sleeve length",new String[]{"Original game choice","Short sleeves","Long sleeves · original shirt","Long sleeves · undershirt","Long sleeves · high-neck undershirt"},old.equals("short")?1:old.equals("long")?2:old.equals("inner")?3:old.equals("highneck")?4:0);String so=values.optString("socks","original");socks=spinner(a,col,"Socks length",new String[]{"Original game choice","Normal","Long","Short"},so.equals("normal")?1:so.equals("long")?2:so.equals("short")?3:0);}
 if(section==1){JSONObject old=values.optJSONObject("accessories");String[] labels={"Short tights","Long tights","Left wrist tape","Right wrist tape","Ankle tape","Outfield gloves","Undershirt · normal neck","Undershirt · high neck"};for(int i=0;i<8;i++)gear[i]=spinner(a,col,labels[i],new String[]{"Original game choice","Off","On"},old==null?0:old.optInt(String.valueOf(new int[]{0,1,4,5,6,7,8,9}[i]),0));}
 if(section==2){ProfileEditor.button(a,col,player,"Club & Nationality","affiliation");JSONArray rows=data.optJSONArray("backgrounds");String[] labels=new String[rows.length()+1];labels[0]="Default card background";int selected=0;for(int i=0;i<rows.length();i++){donors[i+1]=rows.optLong(i);JSONObject names=data.optJSONObject("background_names");labels[i+1]=names==null?"Background":names.optString(String.valueOf(donors[i+1]),"Background");if(values.optLong("background",0)==donors[i+1])selected=i+1;}bg=spinner(a,col,"Copy background style; keep this player's portrait",labels,selected);}
 final Spinner fs=sleeve,fb=bg,fso=socks;AlertDialog d=new AlertDialog.Builder(a).setTitle(section==0?"Sleeves":section==1?"Accessories":"Card Background").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setOnClickListener(v->{try{if(section==0){int sp=fs.getSelectedItemPosition();values.put("sleeve",sp==0&&values.optString("sleeve","none").equals("none")?"none":new String[]{"original","short","long","inner","highneck"}[sp]);values.put("socks",new String[]{"original","normal","long","short"}[fso.getSelectedItemPosition()]);}if(section==1){JSONObject g=new JSONObject();for(int i=0;i<8;i++)g.put(String.valueOf(new int[]{0,1,4,5,6,7,8,9}[i]),gear[i].getSelectedItemPosition());values.put("accessories",g);}if(section==2)values.put("background",donors[fb.getSelectedItemPosition()]);JSONObject request=new JSONObject(player.toString()).put("values",values).put("section",section==0?"sleeve":section==1?"accessories":"background");d.getButton(-1).setEnabled(false);new Thread(()->{try{JSONObject result=new JSONObject(manage(a,"ui710_equipment_apply",request));if(!result.optBoolean("saved"))throw new Exception("Save not confirmed");a.runOnUiThread(()->{d.dismiss();Toast.makeText(a,"Saved. Reopen the app.",Toast.LENGTH_LONG).show();});}catch(Exception e){a.runOnUiThread(()->{d.getButton(-1).setEnabled(true);error(a,e);});}},"EquipmentSave").start();}catch(Exception e){error(a,e);}});
 }catch(Exception e){error(a,e);}}
}
